// ---------- schema (baked in; users never pick a type) ----------
export type ColKind = 'date' | 'cat' | 'id' | 'int' | 'bool' | 'text';

export interface ColumnDef {
  name: string;          // column name in the parquet
  label: string;         // human label
  kind: ColKind;
  filterable: boolean;   // appears in the filter panel
  groupable: boolean;    // can be used as X / series / pivot dim / custom-category base
}

