// ---------- lens: the cohort guard ----------
export type Lens = 'filings' | 'dispositions' | 'all';
export const LENS_INFO: Record<Lens, { label: string; dateField: string; windowFlag: string | null; blurb: string }> = {
  filings:      { label: 'Filings',      dateField: 'filing_date',      windowFlag: 'filed_in_window',
                  blurb: 'Charges entering the system, Jan 2022 - Dec 2025. Time axis = filing date.' },
  dispositions: { label: 'Dispositions', dateField: 'disposition_date', windowFlag: 'disposed_in_window',
                  blurb: 'Charges resolved, Jan 2022 - Dec 2025, including cases filed earlier. Time axis = disposition date.' },
  all:          { label: 'Both',         dateField: 'filing_date',      windowFlag: null,
                  blurb: 'Filed in the window, resolved in it, or both: every charge row. The filing-date axis reaches back to 2004 for backlog charges.' },
};

// ---------- measures ----------
export type Measure = 'charges' | 'cases' | 'people';
export const MEASURES: Record<Measure, string> = {
  charges: 'Charges', cases: 'Distinct cases', people: 'Distinct people',
};

// ---------- custom categories (user-defined groupings) ----------
export interface Bucket { name: string; values: string[] }
export interface Grouping {
  id: string;            // stable, e.g. 'g_1699...'
  name: string;          // e.g. 'Outcome family'
  column: string;        // base categorical column name
  buckets: Bucket[];     // a value appears in at most one bucket
  otherLabel: string;    // label for unassigned values, default 'Other'
}

// A dimension is either a raw column or a user grouping
export type Dim = { kind: 'col'; col: string } | { kind: 'grouping'; groupingId: string };

// ---------- view state (URL-serializable) ----------
export type ChartType = 'line' | 'bar' | 'stackedBar' | 'pctBar' | 'area' | 'heatmap' | 'pivot' | 'table';
export type Granularity = 'month' | 'quarter' | 'year';

export interface ViewState {
  lens: Lens;
  chart: ChartType;
  x: Dim | null;                    // for time charts: {kind:'col', col: <lens dateField>}
  series: Dim | null;               // color / stacking dimension
  granularity: Granularity;
  measure: Measure;
  pct: boolean;                     // show % instead of raw counts
  pctDenom: 'view' | 'lens';        // 'view' = share within filtered view; 'lens' = share of ALL lens rows per x
  filters: Record<string, string[]>; // col -> selected values (empty/absent = all); date cols excluded
  dateFrom: string | null;          // 'YYYY-MM-DD' applied to the lens date field
  dateTo: string | null;
}

export const DEFAULT_VIEW: ViewState = {
  lens: 'filings', chart: 'line', x: { kind: 'col', col: 'filing_date' }, series: null,
  granularity: 'month', measure: 'charges', pct: false, pctDenom: 'view', filters: {}, dateFrom: null, dateTo: null,
};

// ---------- engine API (implemented in src/engine/index.ts) ----------
export interface Dataset {
  rowCount: number;
  // categorical columns: dictionary + per-row codes (code -1 = null)
  cats: Record<string, { dict: string[]; codes: Int32Array }>;
  // date columns: days since epoch per row (NaN/-1e9 sentinel for null)
  dates: Record<string, Int32Array>;
  ids: Record<string, Int32Array>;   // case_id, person_id, count
  bools: Record<string, Uint8Array>; // filed_in_window, disposed_in_window
  text: Record<string, string[]>;    // charge_description, icr, charge_code
}

export interface AggRow { x: string; series: string | null; value: number }
export interface AggResult {
  rows: AggRow[];
  xOrder: string[];        // display order for x values
  seriesOrder: string[];   // display order for series values
  total: number;           // measure over the whole filtered set (for pct)
  filteredRowCount: number;
  /** Present when pct && pctDenom==='lens': x -> UNFILTERED measure total (lens window + dates only). */
  xBaseline?: Record<string, number>;
}

export interface Notice { level: 'warn' | 'info'; title: string; detail: string }

/**
 * Engine exports (src/engine/index.ts must export exactly these):
 *   loadDataset(url: string): Promise<Dataset>
 *   aggregate(ds: Dataset, view: ViewState, groupings: Grouping[]): AggResult
 *   distinctValues(ds: Dataset, col: string): string[]          // sorted, non-null
 *   noticesFor(view: ViewState, groupings: Grouping[]): Notice[]
 *   encodeView(view: ViewState): string                          // URL-hash safe
 *   decodeView(hash: string): ViewState | null
 *   loadGroupings(): Grouping[]                                  // localStorage
 *   saveGroupings(g: Grouping[]): void
 *   PRESET_GROUPINGS: Grouping[]                                 // shipped examples
 *   aggToCsv(r: AggResult, view: ViewState): string              // current view as CSV text
 */

